// Calculation algorithm specialized for Zagazig transit providing real street trajectories
export function calculateZagazigTripRoute(fromName: string, toName: string): CalculatedRoute | null {
  const fromStation = ZAGAZIG_STATIONS.find(
    s => s.name.toLowerCase().includes(fromName.toLowerCase()) || 
         s.id.toLowerCase() === fromName.toLowerCase() ||
         fromName.toLowerCase().includes(s.name.toLowerCase())
  ) || ZAGAZIG_STATIONS[1]; // default: Mawqaf El-Ahrar

  const toStation = ZAGAZIG_STATIONS.find(
    s => s.name.toLowerCase().includes(toName.toLowerCase()) || 
         s.id.toLowerCase() === toName.toLowerCase() ||
         toName.toLowerCase().includes(s.name.toLowerCase())
  ) || ZAGAZIG_STATIONS[3]; // default: Zagazig University

  if (fromStation.id === toStation.id) {
    return {
      id: `route-same-${fromStation.id}`,
      fromStation: fromStation.name,
      toStation: toStation.name,
      totalDurationMins: 0,
      totalStops: 0,
      totalFare: 0,
      transfersCount: 0,
      type: 'fastest',
      pathCoords: [{ x: fromStation.x ?? 0, y: fromStation.y ?? 0 }],
      pathLatLngs: [[fromStation.lat, fromStation.lng]],
      streetGuide: ['أنت بالفعل في وجهتك المحددة.'],
      legs: []
    };
  }

  // 1. From Ahrar to Zagazig University (Most common transit flow in Zagazig)
  if (
    (fromStation.id === 'mawqaf-ahrar-gedid' || fromStation.id === 'mostashfa-ahrar-taleemi') &&
    (toStation.id === 'zagazig-univ-main' || toStation.id === 'zagazig-univ-hospitals')
  ) {
    const line2 = ZAGAZIG_TRANSIT_LINES.find(l => l.id === 'service-ahrar-mahatta')!;
    const line1 = ZAGAZIG_TRANSIT_LINES.find(l => l.id === 'service-zeraa-univ')!;

    // Street path for leg 1: Ahrar to Zeraa
    const leg1Path: [number, number][] = [
      [30.5622, 31.4875], // موقف الأحرار
      [30.5660, 31.4885], // طريق الأحرار
      [30.5695, 31.4920], // تقاطع شرويدة
      [30.5740, 31.4980], // حي الزهور
      [30.5732, 31.5120]  // ميدان الزراعة (محطة التبديل)
    ];

    // Street path for leg 2: Zeraa to University
    const leg2Path: [number, number][] = [
      [30.5732, 31.5120], // ميدان الزراعة
      [30.5755, 31.5085], // شارع فاروق
      [30.5810, 31.5038], // شارع الجلاء
      [30.5840, 31.5035], // ميدان طلعت حرب
      [30.5877, 31.5020], // محطة قطار الزقازيق
      [30.5882, 31.4998], // كورنيش بحر مويس
      [30.5880, 31.4880], // مستشفيات الجامعة
      [30.5894, 31.4820]  // بوابة الجامعة الرئيسية
    ];

    const fullStreetPath = [...leg1Path, ...leg2Path.slice(1)];

    return {
      id: 'route-ahrar-to-univ',
      fromStation: fromStation.name,
      toStation: toStation.name,
      totalDurationMins: 22,
      totalStops: 5,
      totalFare: 9.0,
      transfersCount: 1,
      type: 'fastest',
      pathCoords: [
        { x: fromStation.x ?? 420, y: fromStation.y ?? 720 },
        { x: 580, y: 620 },
        { x: 500, y: 450 },
        { x: toStation.x ?? 350, y: toStation.y ?? 430 }
      ],
      pathLatLngs: fullStreetPath,
      streetGuide: [
        '١. اركب سرفيس خط ٢ من موقف الأحرار الجديد وسر عبر طريق الأحرار ثم حي الزهور حتى ميدان الزراعة (١٠ دقائق - ٤.٥ ج).',
        '٢. انزل عند محطة التبديل بميدان الزراعة واركب سرفيس خط ١ (الزراعة - الجامعة).',
        '٣. سيسير السرفيس في شارع فاروق ← ميدان طلعت حرب ← محطة السكة الحديد ← كورنيش بحر مويس ← شارع السلام ومستشفيات الجامعة ← حتى البوابة الرئيسية للجامعة (١٢ دقيقة - ٤.٥ ج).'
      ],
      legs: [
        {
          mode: 'bus',
          lineName: line2.name,
          lineCode: line2.lineCode,
          fromStation: fromStation.name,
          toStation: 'ميدان وموقف الزراعة',
          stopsCount: 2,
          durationMins: 10,
          fare: 4.5,
          color: 'var(--color-danger)',
          stopsList: [fromStation.name, 'حي الزهور وشارع فاروق', 'ميدان وموقف الزراعة'],
          streetDirections: ['طريق الأحرار الرئيسي', 'منزل كوبري شرويدة', 'حي الزهور', 'ميدان الزراعة'],
          legPathLatLngs: leg1Path
        },
        {
          mode: 'bus',
          lineName: line1.name,
          lineCode: line1.lineCode,
          fromStation: 'ميدان وموقف الزراعة',
          toStation: toStation.name,
          stopsCount: 3,
          durationMins: 12,
          fare: 4.5,
          color: 'var(--color-primary)',
          stopsList: ['ميدان وموقف الزراعة', 'ميدان طلعت حرب', 'محطة قطارات الزقازيق', 'مستشفيات الجامعة', toStation.name],
          streetDirections: ['شارع فاروق', 'شارع الجلاء', 'ميدان طلعت حرب', 'محطة السكة الحديد', 'شارع السلام', 'بوابة مجمع الكليات'],
          legPathLatLngs: leg2Path
        }
      ]
    };
  }

  // 2. Direct internal Service (e.g. Zeraa to University or Mahatta to Qawmeya)
  const sharedLine = ZAGAZIG_TRANSIT_LINES.find(line => 
    line.stationIds.includes(fromStation.id) && line.stationIds.includes(toStation.id)
  );

  if (sharedLine) {
    const fromIdx = sharedLine.stationIds.indexOf(fromStation.id);
    const toIdx = sharedLine.stationIds.indexOf(toStation.id);
    const slice = fromIdx < toIdx 
      ? sharedLine.stationIds.slice(fromIdx, toIdx + 1)
      : sharedLine.stationIds.slice(toIdx, fromIdx + 1).reverse();
    
    const segmentStations = slice.map(id => ZAGAZIG_STATIONS.find(s => s.id === id)!).filter(Boolean);
    const stopsCount = Math.max(1, segmentStations.length - 1);
    const duration = stopsCount * 4 + 4;
    const fare = sharedLine.mode === 'train' ? 25 : sharedLine.mode === 'microbus' ? 18 : 4.5;

    // Extract slice of detailed street points if available
    const detailedPath = sharedLine.detailedPathLatLngs.length >= 2 
      ? (fromIdx <= toIdx ? sharedLine.detailedPathLatLngs : [...sharedLine.detailedPathLatLngs].reverse())
      : segmentStations.map(s => [s.lat, s.lng] as [number, number]);

    return {
      id: `route-direct-${fromStation.id}-${toStation.id}`,
      fromStation: fromStation.name,
      toStation: toStation.name,
      totalDurationMins: duration,
      totalStops: stopsCount,
      totalFare: fare,
      transfersCount: 0,
      type: 'fastest',
      pathCoords: segmentStations.map(s => ({ x: s.x ?? 0, y: s.y ?? 0 })),
      pathLatLngs: detailedPath,
      streetGuide: [
        `اركب مباشرة ${sharedLine.name} من ${fromStation.name}.`,
        `سيسير المسار عبر الشوارع التالية: ${sharedLine.streetPathDescription || segmentStations.map(s => s.name).join(' ← ')}.`,
        `الوصول مباشرة إلى ${toStation.name} بدون أي تبديل.`
      ],
      legs: [
        {
          mode: sharedLine.mode,
          lineName: sharedLine.name,
          lineCode: sharedLine.lineCode,
          fromStation: fromStation.name,
          toStation: toStation.name,
          stopsCount,
          durationMins: duration,
          fare,
          color: sharedLine.color,
          stopsList: segmentStations.map(s => s.name),
          streetDirections: sharedLine.streetsList || segmentStations.map(s => s.name),
          legPathLatLngs: detailedPath
        }
      ]
    };
  }

  // 3. Regional Trip to 10th of Ramadan / Cairo / Ismailia / Bilbeis / Minya / Faqous / Mansoura
  if (['tenth-of-ramadan', 'cairo-ramses-station', 'ismailia-station', 'mansoura-station', 'bilbeis-city', 'minya-el-qamh', 'abou-hammad', 'faqous-city'].includes(toStation.id)) {
    const hub = (toStation.mode === 'train') 
      ? ZAGAZIG_STATIONS.find(s => s.id === 'zag-railway-station')! 
      : ZAGAZIG_STATIONS.find(s => s.id === 'mawqaf-ahrar-gedid')!;

    const leg1Fare = 4.5;
    const fareMap: Record<string, number> = {
      'tenth-of-ramadan': 14.50,
      'cairo-ramses-station': 34.50,
      'ismailia-station': 33.00,
      'mansoura-station': 21.00,
      'bilbeis-city': 8.50,
      'minya-el-qamh': 7.00,
      'abou-hammad': 6.00,
      'faqous-city': 14.00
    };
    const leg2Fare = fareMap[toStation.id] || 15.0;
    const leg2Duration = toStation.id === 'tenth-of-ramadan' ? 35 : toStation.id === 'cairo-ramses-station' ? 75 : 45;

    const regionalLine = ZAGAZIG_TRANSIT_LINES.find(l => l.stationIds.includes(toStation.id));
    const regPath = regionalLine?.detailedPathLatLngs || [[hub.lat, hub.lng], [toStation.lat, toStation.lng]];

    const localLegPath: [number, number][] = [
      [fromStation.lat, fromStation.lng],
      [hub.lat, hub.lng]
    ];

    return {
      id: `route-regional-${toStation.id}`,
      fromStation: fromStation.name,
      toStation: toStation.name,
      totalDurationMins: 15 + leg2Duration,
      totalStops: 4,
      totalFare: leg1Fare + leg2Fare,
      transfersCount: 1,
      type: 'fastest',
      pathCoords: [
        { x: fromStation.x ?? 0, y: fromStation.y ?? 0 },
        { x: hub.x ?? 0, y: hub.y ?? 0 },
        { x: toStation.x ?? 0, y: toStation.y ?? 0 }
      ],
      pathLatLngs: [...localLegPath, ...regPath],
      streetGuide: [
        `١. اركب سرفيس داخلي للوصول من ${fromStation.name} إلى ${hub.name} (١٥ دقيقة - ٤.٥ ج).`,
        `٢. من ${hub.name}، توجه إلى رصيف وحارة السفر المباشرة باتجاه ${toStation.name} (التذكرة: ${leg2Fare} ج).`
      ],
      legs: [
        {
          mode: 'bus',
          lineName: 'سرفيس داخلي للوصول إلى الموقف/المحطة',
          lineCode: 'سرفيس الزقازيق',
          fromStation: fromStation.name,
          toStation: hub.name,
          stopsCount: 2,
          durationMins: 15,
          fare: leg1Fare,
          color: 'var(--color-primary)',
          stopsList: [fromStation.name, hub.name],
          legPathLatLngs: localLegPath
        },
        {
          mode: toStation.mode,
          lineName: toStation.mode === 'train' ? 'قطار السكة الحديد المباشر' : 'ميكروباص الأقاليم المباشر',
          lineCode: 'خط السفر السريع',
          fromStation: hub.name,
          toStation: toStation.name,
          stopsCount: 2,
          durationMins: leg2Duration,
          fare: leg2Fare,
          color: toStation.mode === 'train' ? 'var(--color-orange-dark)' : 'var(--color-text-muted)',
          stopsList: [hub.name, toStation.name],
          legPathLatLngs: regPath
        }
      ]
    };
  }

  // 4. Default transfer via Mahatta or Zeraa with street trajectories
  const transferStation = ZAGAZIG_STATIONS.find(s => s.id === 'zag-railway-station')!;
  
  const step1Path: [number, number][] = [
    [fromStation.lat, fromStation.lng],
    [30.5840, 31.5035], // ميدان طلعت حرب
    [transferStation.lat, transferStation.lng]
  ];

  const step2Path: [number, number][] = [
    [transferStation.lat, transferStation.lng],
    [30.5910, 31.5050], // كوبري الممر
    [toStation.lat, toStation.lng]
  ];

  return {
    id: `route-via-mahatta-${fromStation.id}-${toStation.id}`,
    fromStation: fromStation.name,
    toStation: toStation.name,
    totalDurationMins: 20,
    totalStops: 4,
    totalFare: 9.0,
    transfersCount: 1,
    type: 'fastest',
    pathCoords: [
      { x: fromStation.x ?? 0, y: fromStation.y ?? 0 },
      { x: transferStation.x ?? 500, y: transferStation.y ?? 450 },
      { x: toStation.x ?? 0, y: toStation.y ?? 0 }
    ],
    pathLatLngs: [...step1Path, ...step2Path.slice(1)],
    streetGuide: [
      `١. اركب سرفيس الزقازيق من ${fromStation.name} إلى محطة قطار الزقازيق (نقطة التبديل المركزية).`,
      `٢. من المحطة، استقل السرفيس المتجه إلى ${toStation.name}.`
    ],
    legs: [
      {
        mode: 'bus',
        lineName: 'سرفيس الزقازيق (المرحلة الأولى)',
        lineCode: 'خط سرفيس',
        fromStation: fromStation.name,
        toStation: transferStation.name,
        stopsCount: 2,
        durationMins: 10,
        fare: 4.5,
        color: 'var(--color-primary)',
        stopsList: [fromStation.name, transferStation.name],
        legPathLatLngs: step1Path
      },
      {
        mode: 'bus',
        lineName: 'سرفيس الزقازيق (المرحلة الثانية)',
        lineCode: 'خط سرفيس',
        fromStation: transferStation.name,
        toStation: toStation.name,
        stopsCount: 2,
        durationMins: 10,
        fare: 4.5,
        color: 'var(--color-danger)',
        stopsList: [transferStation.name, toStation.name],
        legPathLatLngs: step2Path
      }
    ]
  };
}

