// ==============================
export const OFFICIAL_TARIFFS_2026 = [
  ...ZAGAZIG_OFFICIAL_TARIFFS_2026,
  ...CAIRO_OFFICIAL_TARIFFS_2026.map(item => ({ ...item, city: item.city || 'القاهرة الكبرى' })),
];
export const OFFICIAL_TAXI_METER = CAIRO_OFFICIAL_TAXI_METER;
export const TAXI_METER_RATES = { zagazig: ZAGAZIG_OFFICIAL_TAXI_METER, cairo: CAIRO_OFFICIAL_TAXI_METER };
export const TERMINAL_LOCATIONS = [...ZAGAZIG_TERMINAL_LOCATIONS, ...CAIRO_TERMINAL_LOCATIONS];
export const STATIONS = [...ZAGAZIG_STATIONS, ...CAIRO_STATIONS];
export const TRANSIT_LINES = [...ZAGAZIG_TRANSIT_LINES, ...CAIRO_TRANSIT_LINES];
export const INITIAL_USER_PROFILE = CAIRO_INITIAL_USER_PROFILE;

export const CITY_DATA = {
  zagazig: { stations: ZAGAZIG_STATIONS, lines: ZAGAZIG_TRANSIT_LINES, terminals: ZAGAZIG_TERMINAL_LOCATIONS, tariffs: ZAGAZIG_OFFICIAL_TARIFFS_2026 },
  cairo: { stations: CAIRO_STATIONS, lines: CAIRO_TRANSIT_LINES, terminals: CAIRO_TERMINAL_LOCATIONS, tariffs: CAIRO_OFFICIAL_TARIFFS_2026 },
};

export function calculateTripRoute(fromName: string, toName: string): CalculatedRoute | null {
  const query = `${fromName} ${toName}`.toLowerCase();
  const isCairo = query.includes('القاهرة') || query.includes('الجيزة') || query.includes('المترو') || query.includes('مونوريل') || query.includes('العاصمة') ||
    CAIRO_STATIONS.some(station => query.includes(station.name.toLowerCase()));
  return isCairo ? calculateCairoTripRoute(fromName, toName) : calculateZagazigTripRoute(fromName, toName);
}
